import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_edges = []
    total_weight = 0
    for weight, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u, v, weight))
            total_weight += weight
    return mst_edges

def critical_edges(n, edges, mst_edges):
    critical = [False] * len(edges)
    for i, (u, v, _) in enumerate(mst_edges):
        parent = list(range(n + 1))
        rank = [0] * (n + 1)
        total_weight = 0
        for j, (w, a, b) in enumerate(edges):
            if j != i and find(parent, a) != find(parent, b):
                union(parent, rank, a, b)
                total_weight += w
        if total_weight > sum(weight for _, _, weight in mst_edges):
            critical[i] = True
    return critical

def max_energy_for_corridors(n, m, corridors):
    edges = [(e, a, b) for a, b, e in corridors]
    edges.sort()
    mst_edges = kruskal(n, edges)
    critical = critical_edges(n, edges, mst_edges)
    mst_set = set((min(u, v), max(u, v)) for u, v, _ in mst_edges)
    result = []
    for a, b, e in corridors:
        ab = (min(a, b), max(a, b))
        if ab in mst_set:
            if critical[mst_edges.index((ab[0], ab[1], e))]:
                result.append(e)
            else:
                for weight, u, v in reversed(edges):
                    if (u, v) == ab:
                        break
                    if (min(u, v), max(u, v)) in mst_set:
                        result.append(weight)
                        break
        else:
            result.append(e)
    return result

